namespace tiny_muai\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_value;
use tiny_muai\utils;

/**
 * External API: build a prompt server-side and call core_ai generate_text.
 *
 * @package    tiny_muai
 * @copyright  2026 Andrew Rowatt <A.J.Rowatt@massey.ac.nz>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class get_ai_response extends external_api {
    /**
     * Parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'contextid' => new external_value(
                PARAM_INT,
                'The Moodle context id of the editor instance',
                VALUE_REQUIRED,
            ),
            'page' => new external_value(
                PARAM_ALPHANUMEXT,
                'The HTML id of the body tag of the page the editor is on',
                VALUE_REQUIRED,
            ),
            'editorcontext' => new external_value(
                PARAM_ALPHANUMEXT,
                'The HTML id of the textarea associated with the editor instance',
                VALUE_REQUIRED,
            ),
            'editorcontent' => new external_value(
                PARAM_RAW,
                'The text content of the editor',
                VALUE_REQUIRED,
            ),
            'name' => new external_value(
                PARAM_TEXT,
                'The value of the HTML field with id "id_name" on the page',
                VALUE_DEFAULT,
                '',
            ),
        ]);
    }

    /**
     * Build the prompt and request a generation from the AI manager.
     *
     * @param int $contextid
     * @param string $page
     * @param string $editorcontext
     * @param string $editorcontent
     * @return string The generated text.
     */
    public static function execute(
        int $contextid,
        string $page,
        string $editorcontext,
        string $editorcontent,
        string $name = '',
    ): string {
        [
            'contextid' => $contextid,
            'page' => $page,
            'editorcontext' => $editorcontext,
            'editorcontent' => $editorcontent,
            'name' => $name,
        ] = self::validate_parameters(self::execute_parameters(), [
            'contextid' => $contextid,
            'page' => $page,
            'editorcontext' => $editorcontext,
            'editorcontent' => $editorcontent,
            'name' => $name,
        ]);

        $context = \core\context::instance_by_id($contextid);
        self::validate_context($context);

        if (!\aiplacement_editor\utils::is_html_editor_placement_action_available(
            $context,
            'generate_text',
            \core_ai\aiactions\generate_text::class,
        )) {
            throw new \moodle_exception('noeditor', 'aiplacement_editor');
        }

        return utils::generate_ai_response($contextid, $page, $editorcontext, $editorcontent, $name);
    }

    /**
     * Returns: a single text value.
     *
     * @return external_value
     */
    public static function execute_returns(): external_value {
        return new external_value(
            PARAM_RAW,
            'The text generated by the AI service',
        );
    }
}
